return ['domain'=>'zinn-cache-pro','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'mn','project-id-version'=>'zinn-cache-pro','pot-creation-date'=>'2026-09-03T18:22:39+00:00','po-revision-date'=>'2026-09-03T18:22:39+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Cache Engine'=>'Zinn® Cache Engine','https://zinndigital.com/wordpress-plugins/zinn-cache-pro'=>'https://zinndigital.com/wordpress-plugins/zinn-cache-pro','A complete caching and optimisation engine for WordPress: full-page cache, object cache, database cleanup and CSS/JS optimisation. Install this when your host does not provide a cache layer of its own — on Zinn Digital® hosting install Zinn® Cache instead. Full-page caching requires a LiteSpeed or OpenLiteSpeed server with the LSCache module. A GPLv3 fork of the LiteSpeed Cache plugin.'=>'WordPress-ийн кэш болон оновчлолын бүрэн хэмжээний систем: бүтэн хуудасны кэш, объект кэш, өгөгдлийн санг цэвэрлэх болон CSS/JS оновчлол. Таны хостинг өөрийн гэсэн кэшийн түвшинг хангаагүй үед үүнийг суулгана уу — Zinn Digital® хостинг дээр оронд нь Zinn® Cache суулгана уу. Бүтэн хуудасны кэшлэлт нь LSCache модуль бүхий LiteSpeed эсвэл OpenLiteSpeed сервер шаарддаг. LiteSpeed Cache залгаасын GPLv3 форк.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','%d hours'=>'%d цаг','%d hour'=>'%d цаг','%d minutes'=>'%d минут','%d minute'=>'%d минут','Purged All!'=>'Бүгдийг устгалаа!','Purged the blog!'=>'Блогыг цэвэрлэлээ!','Purged the URL!'=>'URL-ийг устгалаа!','Purged!'=>'Цэвэрлэгдлээ!','Failed to upgrade.'=>'Шинэчлэх явцад алдаа гарлаа.','Upgraded successfully.'=>'Амжилттай шинэчлэгдлээ.','Dashboard'=>'Хяналтын самбар','OptimaX'=>'OptimaX','Presets'=>'Урьдчилж тохируулгууд','General'=>'Ерөнхий','Cache'=>'Кэш','CDN'=>'CDN','Image Optimization'=>'Зургийн оновчлол','Page Optimization'=>'Хуудасны оновчлол','Database'=>'Өгөгдлийн сан','Crawler'=>'Кроулер','Toolbox'=>